Translate("zhCN", "druids-of-the-fang", {
	title = "尖牙德鲁伊",
	aliases = { "尖牙德鲁伊", "尖牙领主" },
	sections = {
		{
			title = "概述",
			text = [=[尖牙德鲁伊是{link:naralex}纳拉雷克斯{/link}堕落的追随者。他们作为一个高尚的德鲁伊教团来到{link:wailing-caverns}哀嚎洞穴{/link}，本想治愈{link:the-barrens}贫瘠之地{/link}。当他们主人的梦变成噩梦时，他们中的大多数也随他一同堕落了。如今他们面覆鳞片，化身蛇形，企图按照他们自己扭曲的梦境重塑这片土地。]=],
		},
		{
			title = "教团",
			text = [=[四位首领——尖牙领主——指挥着他们：{link:lady-anacondra}安娜科德拉{/link}、{link:lord-cobrahn}考布莱恩{/link}、{link:lord-pythas}皮萨斯{/link}，以及他们的首领{link:lord-serpentis}瑟芬迪斯{/link}。每人都持有一颗梦境宝石。在他们之下，尖牙德鲁伊把变异的毒蛇和迅猛龙当作自己的野兽，其中一些人在地上的{link:burning-steppes}平原{/link}上行走。其中一个名叫博艾恩的，曾在洞穴所在的山丘附近出现。少数保持了心智的信徒，其中包括纳尔{link:guard-parker}帕克{/link}、厄布鲁和在洞中等候的那位信徒，如今正在对抗他们堕落的兄弟。]=],
		},
		{
			title = "德鲁伊所见",
			text = [=[{link:hamuul-runetotem}哈缪尔·符文图腾{/link}进入梦境，想了解是什么在毒害{link:the-barrens}贫瘠之地{/link}。他看到了一个德鲁伊教派，他们的目标曾经是高尚的，却迷失了方向，为渗透大地的污染效力。他年事已高，无法久留。{link:nara-wildmane}纳拉·蛮鬃{/link}留了下来，看到了他们的面孔。她说，那些面孔至今仍萦绕着她。]=],
		},
	},
})
